   230    /// Set the error limit - the maximum number of errors after which to abort
   231    /// compilation. Zero indicates no limit.
   232    void setErrorLimit(unsigned errorLimit) {
   233      errorLimit_ = errorLimit == 0 ? UINT_MAX : errorLimit;
